    const employees = counts.employees ?? counts.employee_count ?? 0, projectCount = counts.projects ?? counts.project_count ?? projects.length, assignments = counts.assignments ?? counts.assignment_count ?? 0, invitations = counts.invitations ?? counts.pending_invitations ?? 0;
