  const renderers={dashboard:renderDashboard,employees:renderEmployees,projects:renderProjects,invitations:renderInvitations,assignments:renderAssignments,reviews:renderReviews,catalog:renderCatalog,analytics:renderAnalytics,events:renderEvents};
  const titles={dashboard:'Обзор',employees:'Сотрудники',projects:'Проекты',search:'Поиск специалистов',invitations:'Приглашения',assignments:'Назначения',reviews:'Отзывы',catalog:'Компетенции',analytics:'Аналитика',events:'История событий'};
  function restrictLinks() {
    const access={employees:has('EMPLOYEE','EDITOR','MANAGER','ANALYST'),projects:has('MANAGER','ANALYST'),search:has('MANAGER'),invitations:has('EMPLOYEE'),assignments:has('EMPLOYEE','MANAGER','ANALYST'),reviews:has('EMPLOYEE','MANAGER','ANALYST'),events:has('EDITOR','MANAGER','ANALYST'),catalog:node===0&&has('CATALOG_ADMIN'),analytics:node===0&&has('ANALYST')};
    view.querySelectorAll('a[href^="/"]').forEach(link=>{const section=link.getAttribute('href').split('/')[1].split('?')[0];if(access[section]===false){const text=document.createElement('span');text.className='muted small';text.textContent=link.textContent;link.replaceWith(text);}});
  }
  async function load(showSkeleton=true) {
    const sequence=++state.sequence;const parts=location.pathname.split('/').filter(Boolean);const page=parts[0]||'dashboard';document.title=(titles[page]||'Рабочее пространство')+' — Cross-Team';document.getElementById('breadcrumb').textContent=titles[page]||'Обзор';document.querySelectorAll('[data-route]').forEach(link=>{const active=link.dataset.route===(page==='dashboard'?'/':'/'+page);link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});if(showSkeleton)view.innerHTML=skeleton();
    try {
      if(page==='search'){const params=new URLSearchParams(location.search);const shouldSearch=params.has('position_id')||params.has('region_mode');const data=shouldSearch?await api('/api/search?'+params):null;if(sequence!==state.sequence)return;state.data=data;await renderSearch(data);return;}
      const detail=parts.length===3&&['employees','projects'].includes(page);const data=await api('/api/'+page+(detail?'/'+parts[1]+'/'+parts[2]:''));if(sequence!==state.sequence)return;state.data=data;state.items.clear();if(detail){(page==='employees'?renderEmployee:renderProject)(data);}else{(renderers[page]||renderDashboard)(data);}
    }catch(error){if(sequence===state.sequence)renderError(error);}finally{if(sequence===state.sequence)restrictLinks();}
  }
  document.addEventListener('click',async event=>{
    const close=event.target.closest('[data-close]');if(close){closeDialog();return;}
    const mode=event.target.closest('[data-mode]');if(mode){state.mode=mode.dataset.mode;document.querySelectorAll('[data-mode]').forEach(el=>{el.classList.toggle('active',el===mode);el.setAttribute('aria-pressed',String(el===mode));});return;}
    const pageButton=event.target.closest('[data-search-page]');if(pageButton){await performSearch(Number(pageButton.dataset.searchPage));return;}
    const listPage=event.target.closest('[data-list-page]');if(listPage){state.listPage=Number(listPage.dataset.listPage);state.items.clear();renderEmployees(state.data);window.scrollTo({top:0,behavior:'smooth'});return;}
    const button=event.target.closest('[data-action]');if(!button)return;const item=state.items.get(button.dataset.item)||{};button.disabled=true;try{await dispatch(button.dataset.action,item);}catch(error){toast(error.message,true);}finally{button.disabled=false;}
  });
  let filterTimeout;document.addEventListener('input',event=>{if(event.target.id==='skill-filter'){const query=event.target.value.toLowerCase().trim();document.querySelectorAll('.filter-competencies .checkbox-chip').forEach(label=>{label.hidden=!!query&&!label.textContent.toLowerCase().includes(query);});return;}if(event.target.id!=='list-filter')return;const input=event.target;state.filter=input.value;state.listPage=1;clearTimeout(filterTimeout);filterTimeout=setTimeout(()=>{const page=location.pathname.split('/')[1]||'dashboard';const selection=input.selectionStart;state.items.clear();renderers[page]?.(state.data);const next=document.getElementById('list-filter');if(next){next.focus();next.setSelectionRange(selection,selection);}},160);});
  document.addEventListener('submit',event=>{if(event.target.id==='search-form'){event.preventDefault();performSearch();}});
  dialog.addEventListener('click',event=>{if(event.target===dialog){const bounds=dialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)closeDialog();}});dialog.addEventListener('cancel',event=>{if(dialog.querySelector('form')?.dataset.submitting)event.preventDefault();});
  const sidebar=document.getElementById('sidebar'),scrim=document.getElementById('sidebar-scrim'),menu=document.getElementById('menu-toggle');function toggleMenu(open){sidebar.classList.toggle('open',open);scrim.hidden=!open;menu.setAttribute('aria-expanded',String(open));}menu.addEventListener('click',()=>toggleMenu(!sidebar.classList.contains('open')));scrim.addEventListener('click',()=>toggleMenu(false));document.addEventListener('keydown',event=>{if(event.key==='Escape')toggleMenu(false);});
  document.getElementById('today').textContent=new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});const roleLabels={EMPLOYEE:'Сотрудник',EDITOR:'Редактор региона',MANAGER:'Руководитель проекта',CATALOG_ADMIN:'Администратор справочника',ANALYST:'Аналитик'};document.getElementById('user-role').textContent=roles.map(role=>roleLabels[role]||role).join(' · ');load();
